{
  "case_id": "xsu_sg_008_completed_treatment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "met", "reason": "Svaret gengiver korrekt minimumskravet om journalmateriale fra egen læge, speciallæge, hospital eller ambulant klinik, at materialet skal beskrive den varige funktionsnedsættelse, og at epikrise/afslutningsbrev som udgangspunkt indgår ved afsluttet behandling. Afvisningsfølgen er gengivet korrekt efter vejledningen. Ingen af rubrikkens material_errors begås: epikrise gøres ikke til absolut krav, og 'eller' gøres ikke kumulativt."},
    "c02_required_elements_complete": {"label": "met", "reason": "Alle tre kritiske elementer er med: journalmateriale fra de nævnte behandlertyper, beskrivelse af den varige funktionsnedsættelse, og epikrise/afslutningsbrev som udgangspunkt ved afsluttet behandling."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret angiver direkte, hvilken lægelig dokumentation ansøgningen skal indeholde, og hvad der gælder ved afsluttet behandling. Afvisningssætningen er et kort supplement, ikke irrelevant tekst."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret nævner ingen identificerbar kilde (hverken bestemmelse, vejledningsafsnit eller lov). Der står kun 'Udbetaling Danmark', som er en myndighed og ikke en kilde."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde understøtter påstandene."},
    "c07_no_unsupported_legal_additions": {"label": "met", "reason": "Alle udsagn har støtte i vejledningens afsnit 4.1 og SU-bekendtgørelsen § 37, stk. 3. Svaret tilføjer ingen ekstra regel, betingelse eller retsvirkning."},
    "c08_qualifications_and_exceptions": {"label": "met", "reason": "'Som udgangspunkt' er bevaret ved epikrise/afslutningsbrev, og 'som minimum' er bevaret ved journalmaterialet. Afvisningsfølgen er gengivet korrekt. Rubrikkens punkt om, at dokumentets titel ikke i sig selv afgør tilstrækkeligheden, er ikke nævnt, men det er et supplerende element."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Svaret er internt sammenhængende: først minimumskrav, så tillæg ved afsluttet behandling, så følgen af manglende dokumentation. Der er ingen modsigelser."},
    "c10_legal_modality_precision": {"label": "met", "reason": "'Skal som minimum' svarer til kravet i § 37, stk. 3 og vejledningen. 'Som udgangspunkt' gengiver vejledningens 'vil som udgangspunkt' præcist. 'Afviser' svarer til vejledningens formulering. Intet er gjort absolut."}
  },
  "xhaile_coverage": {
    "A30": {"label": "yes", "reason": "Svaret nævner, at når behandlingsforløbet er afsluttet, skal dokumentationen som udgangspunkt også indeholde en epikrise eller et afslutningsbrev."},
    "A32": {"label": "yes", "reason": "Svaret dækker, at dokumentationen som udgangspunkt også indeholder epikrise eller afslutningsbrev ved afsluttet behandling, med forbeholdet 'som udgangspunkt' bevaret."}
  },
  "overall_notes": "Indholdet er juridisk korrekt og komplet, men svaret angiver ingen kilde. Derfor er C04 not_met, mens C05 og C06 er not_assessable efter kildereglen. Svaret bruger 'skal' om epikrisen sammen med 'som udgangspunkt', hvilket stadig bevarer forbeholdet."
}

